namespace sv_89445ae440a24eb1b4bc150d6df2534a;

public enum Theme
{
    Light,
    Dark,
    System
}

public class ThemeInfo
{
    public Theme Theme { get; set; } = Theme.Light;
    public string AccentColor { get; set; } = "#0d6efd";
}

﻿<span class="theme-indicator" style="color: @(Theme?.AccentColor ?? "#0d6efd");">
    Theme: @(Theme?.Theme.ToString() ?? "Light")
</span>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }
}

﻿@rendermode InteractiveServer
@inject CascadingValueSource<ThemeInfo> ThemeSource

<button class="btn btn-sm btn-outline-secondary" @onclick="CycleTheme">
    @GetIcon() @theme.Theme
</button>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private ThemeInfo theme => Theme ?? new();

    private async Task CycleTheme()
    {
        var next = theme.Theme switch
        {
            Theme.Light => Theme.Dark,
            Theme.Dark => Theme.System,
            _ => Theme.Light
        };

        await ThemeSource.NotifyChangedAsync(
            new ThemeInfo { Theme = next, AccentColor = theme.AccentColor });
    }

    private string GetIcon() => theme.Theme switch
    {
        Theme.Dark => "🌙",
        Theme.System => "💻",
        _ => "☀️"
    };
}

﻿@page "/settings"
@rendermode InteractiveServer
@inject CascadingValueSource<ThemeInfo> ThemeSource

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="card mt-3" style="max-width: 400px;">
    <div class="card-body">
        <h5 class="card-title">Theme</h5>

        <div class="mb-3">
            <label class="form-label">Mode</label>
            <select class="form-select" value="@currentTheme" @onchange="OnThemeChanged">
                @foreach (var t in Enum.GetValues<Theme>())
                {
                    <option value="@t">@t</option>
                }
            </select>
        </div>

        <div class="mb-3">
            <label class="form-label">Accent Color</label>
            <input type="color" class="form-control form-control-color"
                   value="@accentColor" @onchange="OnAccentChanged" />
        </div>

        <button class="btn btn-primary" style="background-color: @accentColor; border-color: @accentColor;"
                @onclick="Save">
            Save Preferences
        </button>
    </div>
</div>

@code {
    [CascadingParameter]
    private ThemeInfo? Theme { get; set; }

    private Theme currentTheme;
    private string accentColor = "#0d6efd";

    protected override void OnParametersSet()
    {
        if (Theme is not null)
        {
            currentTheme = Theme.Theme;
            accentColor = Theme.AccentColor;
        }
    }

    private void OnThemeChanged(ChangeEventArgs e)
    {
        if (Enum.TryParse<Theme>(e.Value?.ToString(), out var parsed))
            currentTheme = parsed;
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        accentColor = e.Value?.ToString() ?? accentColor;
    }

    private async Task Save()
    {
        await ThemeSource.NotifyChangedAsync(
            new ThemeInfo { Theme = currentTheme, AccentColor = accentColor });
    }
}

